package dev.veltraph.client.chocolate;
import org.junit.jupiter.api.Test;
import com.google.gson.Gson;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;
class ChocolateQueueRecoveryTest {
    static final long NOW=1500;
    static ChocolateQueueIntent intent(ChocolateQueueManualReconciliationTest.Case c){return ChocolateQueueIntent.capture(c.runtime(),c.profile());}
    static ChocolateFactoryObservation replacement(boolean purchased){var o=ChocolateQueueManualReconciliationTest.observation(purchased);return ChocolateQueueManualReconciliationTest.changed(o,o.scope(),new Object(),new Object(),new Object(),true,true,true,1000,o.rows());}
    static ChocolateQueueRecovery.Inspection inspect(ChocolateQueueIntent intent,boolean purchased){return ChocolateQueueRecovery.inspect(intent,intent.id(),intent.scope(),ChocolateQueueRecovery.DECLARATION,replacement(purchased),0,NOW);}
    static ChocolateFactoryRuntime restarted(){return new ChocolateFactoryRuntime(new ChocolateQueueManualReconciliationTest.Port());}
    @Test void originalIntentRoundTripRetainsQuoteAccountingProtectedFactsAndProfile(){var c=ChocolateQueueManualReconciliationTest.unknown();var i=intent(c);var history=ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode("").withContract(i).with(c.pending()));var roundtrip=history.queueContracts().get(i.id());assertEquals(i,roundtrip);assertEquals("100",roundtrip.price());assertEquals("100",roundtrip.budget());assertEquals("0",roundtrip.reserve());assertEquals("200",roundtrip.beforeBalance());assertEquals(i.protectedFingerprints(),roundtrip.protectedFingerprints());assertEquals(c.profile().encode(),roundtrip.profileJson());assertTrue(roundtrip.originalContextFacts().contains("not persistent account proof"));assertTrue(history.pending());assertTrue(history.receipts().isEmpty());}
    @Test void replacementWorldRequiresExplicitDeclarationThenUnchangedTargetCanCloseWithoutInput(){var c=ChocolateQueueManualReconciliationTest.unknown();var i=intent(c);var declared=inspect(i,false);assertNotSame(c.runtime().selection().observation().session(),declared.observed().session());assertThrows(IllegalArgumentException.class,()->ChocolateQueueRecovery.inspect(i,i.id(),i.scope(),"",declared.observed(),0,NOW));var plan=ChocolateQueueRecovery.prepare(i,c.pending(),declared,false,c.runtime(),NOW);var memory=new AtomicReference<>(ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode("").withContract(i).with(c.pending())));assertTrue(ChocolateManualReconciliationTransaction.commit(plan.pending(),plan.resolved(),j->memory.set(ChocolateFactoryHistory.decode(memory.get().withManualQueueJournal(j))),()->true,()->ChocolateQueueRecovery.unchangedRuntime(c.runtime(),plan),()->c.runtime().closeRecoveryReconciliation(plan),()->c.runtime().restoreOwnedManualClosure(plan.runtimeBefore())));assertEquals(ChocolateFactoryRuntime.State.IDLE,c.runtime().state());assertNull(c.runtime().selection());assertEquals(1,c.port().clicks);assertEquals(0,c.runtime().spent().signum());assertEquals(0,c.runtime().manualDeclaredDebit().signum());assertTrue(c.runtime().acknowledgedUpgrades().isEmpty());assertTrue(memory.get().receipts().isEmpty());assertFalse(memory.get().pending());assertTrue(plan.resolved().reason().contains("account identity UNPROVEN"));assertTrue(plan.resolved().reason().contains("Coin valuation UNKNOWN"));}
    @Test void restartFailedDurabilityKeepsExactOriginalJournalThenExplicitRetryCountsManualDebitOnce(){var c=ChocolateQueueManualReconciliationTest.unknown();var i=intent(c);var history=ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode("").withContract(i).with(c.pending()));var rt=restarted();var plan=ChocolateQueueRecovery.prepare(history.queueContracts().get(i.id()),history.queueIntents().get(i.id()),inspect(i,true),true,rt,NOW);var memory=new AtomicReference<>(history);var disk=new AtomicReference<>(history);assertFalse(ChocolateManualReconciliationTransaction.commit(plan.pending(),plan.resolved(),j->memory.set(ChocolateFactoryHistory.decode(memory.get().withManualQueueJournal(j))),()->false,()->true,()->rt.closeRecoveryReconciliation(plan),()->rt.restoreOwnedManualClosure(plan.runtimeBefore())));assertEquals(c.pending(),memory.get().queueIntents().get(i.id()));assertTrue(disk.get().pending());assertEquals(0,rt.spent().signum());assertEquals(0,rt.manualDeclaredDebit().signum());assertNull(rt.selection());var retry=ChocolateQueueRecovery.prepare(i,memory.get().queueIntents().get(i.id()),inspect(i,true),true,rt,NOW);assertTrue(ChocolateManualReconciliationTransaction.commit(retry.pending(),retry.resolved(),j->memory.set(ChocolateFactoryHistory.decode(memory.get().withManualQueueJournal(j))),()->{disk.set(memory.get());return true;},()->ChocolateQueueRecovery.unchangedRuntime(rt,retry),()->rt.closeRecoveryReconciliation(retry),()->rt.restoreOwnedManualClosure(retry.runtimeBefore())));assertEquals(new BigDecimal("100"),rt.manualDeclaredDebit());assertEquals(0,rt.spent().signum());assertTrue(rt.acknowledgedUpgrades().isEmpty());assertTrue(disk.get().receipts().isEmpty());assertThrows(IllegalArgumentException.class,()->ChocolateQueueRecovery.prepare(i,disk.get().queueIntents().get(i.id()),inspect(i,true),true,rt,NOW));}
    @Test void noSerializedOriginalIntentNeverUsesCurrentProfileAsRecoveryAuthority(){var c=ChocolateQueueManualReconciliationTest.unknown();assertThrows(IllegalArgumentException.class,()->ChocolateQueueRecovery.inspect(null,c.pending().intentId(),"local-test",ChocolateQueueRecovery.DECLARATION,replacement(false),0,NOW));var old=new ChocolateFactoryModule.Journal(1,"local-test","2026-09-30","UNKNOWN","employee","100","0","old schema");var history=ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode("").with(old));assertTrue(history.pending());assertTrue(history.queueContracts().isEmpty());assertEquals("",old.intentId());}
    @Test void exactIDOriginalScopeAndExplicitHumanDeclarationCannotBeOmittedOrReplaced(){var c=ChocolateQueueManualReconciliationTest.unknown();var i=intent(c);for(var args:List.of(List.of("other",i.scope(),ChocolateQueueRecovery.DECLARATION),List.of(i.id(),"foreign",ChocolateQueueRecovery.DECLARATION),List.of(i.id(),i.scope(),"automatic")))assertThrows(IllegalArgumentException.class,()->ChocolateQueueRecovery.inspect(i,args.get(0),args.get(1),args.get(2),replacement(false),0,NOW));assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,c.runtime().state());}
    @Test void staleIncompleteCursorProtectedInventoryHotbarAndForeignScopeInspectionDenied(){var c=ChocolateQueueManualReconciliationTest.unknown();var i=intent(c);var o=replacement(false);var rows=new HashMap<>(o.rows());rows.remove(10);var bad=List.of(ChocolateQueueManualReconciliationTest.changed(o,"foreign",o.session(),o.menu(),o.screen(),true,true,true,1000,o.rows()),ChocolateQueueManualReconciliationTest.changed(o,o.scope(),o.session(),o.menu(),o.screen(),false,true,true,1000,o.rows()),ChocolateQueueManualReconciliationTest.changed(o,o.scope(),o.session(),o.menu(),o.screen(),true,false,true,1000,o.rows()),ChocolateQueueManualReconciliationTest.changed(o,o.scope(),o.session(),o.menu(),o.screen(),true,true,false,1000,o.rows()),ChocolateQueueManualReconciliationTest.changed(o,o.scope(),o.session(),o.menu(),o.screen(),true,true,true,0,o.rows()),ChocolateQueueManualReconciliationTest.changed(o,o.scope(),o.session(),o.menu(),o.screen(),true,true,true,1000,rows));for(var value:bad)assertThrows(IllegalArgumentException.class,()->ChocolateQueueRecovery.inspect(i,i.id(),i.scope(),ChocolateQueueRecovery.DECLARATION,value,0,NOW));assertThrows(IllegalArgumentException.class,()->ChocolateQueueRecovery.inspect(i,i.id(),i.scope(),ChocolateQueueRecovery.DECLARATION,o,1,NOW));}
    @Test void anotherRuntimeIntentOrConflictingOriginalJournalCannotBeAdopted(){var c=ChocolateQueueManualReconciliationTest.unknown();var i=intent(c);var foreign=restarted();assertTrue(foreign.select(c.profile(),ChocolateQueueManualReconciliationTest.observation(false),"employee",new BigDecimal("100"),BigDecimal.ZERO,NOW));assertThrows(IllegalArgumentException.class,()->ChocolateQueueRecovery.prepare(i,c.pending(),inspect(i,false),false,foreign,NOW));assertNotEquals(i.id(),foreign.selection().intentId());var wrong=new ChocolateFactoryModule.Journal(1,i.scope(),"2026-09-30","UNKNOWN","employee","101","0","conflict","0",i.id());assertThrows(IllegalArgumentException.class,()->ChocolateQueueRecovery.prepare(i,wrong,inspect(i,false),false,restarted(),NOW));}
    @Test void observedOutcomeCannotBeBlindlyChangedAndNoJumpOrContradictoryDebit(){var c=ChocolateQueueManualReconciliationTest.unknown();var i=intent(c);assertThrows(IllegalArgumentException.class,()->ChocolateQueueRecovery.prepare(i,c.pending(),inspect(i,false),true,restarted(),NOW));assertThrows(IllegalArgumentException.class,()->ChocolateQueueRecovery.prepare(i,c.pending(),inspect(i,true),false,restarted(),NOW));for(var value:List.of(ChocolateFactoryTest.observation(2,3,"100","jump"),ChocolateFactoryTest.observation(2,2,"50","new"))){var declared=ChocolateQueueRecovery.inspect(i,i.id(),i.scope(),ChocolateQueueRecovery.DECLARATION,value,0,NOW);assertThrows(IllegalArgumentException.class,()->ChocolateQueueRecovery.prepare(i,c.pending(),declared,true,restarted(),NOW));}}
    @Test void successfulWriteThenInspectionDriftOrCloseFailurePreservesPendingAndLedgers(){for(boolean closeFailure:List.of(false,true)){var c=ChocolateQueueManualReconciliationTest.unknown();var i=intent(c);var rt=restarted();var plan=ChocolateQueueRecovery.prepare(i,c.pending(),inspect(i,true),true,rt,NOW);var memory=new AtomicReference<>(ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode("").withContract(i).with(c.pending())));assertFalse(ChocolateManualReconciliationTransaction.commit(plan.pending(),plan.resolved(),j->memory.set(ChocolateFactoryHistory.decode(memory.get().withManualQueueJournal(j))),()->true,()->closeFailure,()->{rt.closeRecoveryReconciliation(plan);throw new IllegalStateException("close callback failed");},()->rt.restoreOwnedManualClosure(plan.runtimeBefore())));assertEquals(c.pending(),memory.get().queueIntents().get(i.id()));assertEquals(0,rt.spent().signum());assertEquals(0,rt.manualDeclaredDebit().signum());assertTrue(rt.acknowledgedUpgrades().isEmpty());assertTrue(memory.get().receipts().isEmpty());}}
    @Test void contractIdentityCannotBeRewrittenAndKnownNativeSpendRemainsSeparate(){var c=ChocolateQueueManualReconciliationTest.unknown();var i=intent(c);var obj=new Gson().toJsonTree(i).getAsJsonObject();obj.addProperty("beforeRevision",99);var conflicting=new Gson().fromJson(obj,ChocolateQueueIntent.class);assertThrows(IllegalArgumentException.class,()->ChocolateFactoryHistory.decode("").withContract(i).withContract(conflicting));var pending=new ChocolateFactoryModule.Journal(1,i.scope(),"2026-09-30","ACKNOWLEDGED_UNPERSISTED",i.upgrade(),i.price(),"100","actual native ACK persistence failed","0",i.id());var rt=restarted();var plan=ChocolateQueueRecovery.prepare(i,pending,inspect(i,true),true,rt,NOW);rt.closeRecoveryReconciliation(plan);assertEquals(new BigDecimal("100"),rt.spent());assertEquals(0,rt.manualDeclaredDebit().signum());assertTrue(rt.acknowledgedUpgrades().isEmpty());assertEquals("0",plan.resolved().manualDeclaredDebit());assertThrows(IllegalArgumentException.class,()->ChocolateQueueRecovery.prepare(i,pending,inspect(i,false),false,restarted(),NOW));}
    @Test void protectedRowDigestUsesExplicitStableFieldsAndRejectsOpaqueObjectToString(){var c=ChocolateQueueManualReconciliationTest.unknown();var o=c.runtime().selection().observation();var reversed=new LinkedHashMap<Integer,ChocolateFactoryObservation.Row>();o.rows().keySet().stream().sorted(Comparator.reverseOrder()).forEach(k->reversed.put(k,o.rows().get(k)));var same=ChocolateQueueManualReconciliationTest.changed(o,o.scope(),new Object(),new Object(),new Object(),true,true,true,9999,reversed);assertEquals(ChocolateQueueIntent.protectedRows(o),ChocolateQueueIntent.protectedRows(same));var row=o.rows().get(10);var changed=new ChocolateFactoryObservation.Row(row.slot(),true,row.itemId(),row.name(),row.count()+1,row.lore(),row.fullIdentity());assertNotEquals(ChocolateQueueIntent.fingerprint(row),ChocolateQueueIntent.fingerprint(changed));assertThrows(IllegalArgumentException.class,()->ChocolateQueueIntent.fingerprint(new Object(){@Override public String toString(){return "opaque-process-dependent";}}));}

    @Test void failedNativeACKPersistenceRetainsOriginalIntentIDAndManualLedgerForRecovery(){var c=ChocolateQueueManualReconciliationTest.unknown();var i=intent(c);var ack=new ChocolateFactoryModule.Journal(1,i.scope(),"2026-09-30","ACKNOWLEDGED",i.upgrade(),i.price(),"100","native observed ACK","0",i.id());var retained=new AtomicReference<ChocolateFactoryModule.Journal>();assertFalse(ChocolateFactoryAcknowledgmentPersistence.confirm(ack,retained::set,()->false));assertEquals("ACKNOWLEDGED_UNPERSISTED",retained.get().status());assertEquals(i.id(),retained.get().intentId());assertEquals("0",retained.get().manualDeclaredDebit());var plan=ChocolateQueueRecovery.prepare(i,retained.get(),inspect(i,true),true,restarted(),NOW);assertEquals("100",plan.resolved().spent());assertEquals("0",plan.resolved().manualDeclaredDebit());}

    @Test void declarationBindsOneFreshInspectionAndDriftMustBeRejectedBeforeWrite(){var c=ChocolateQueueManualReconciliationTest.unknown();var i=intent(c);var declared=inspect(i,false);var writes=new AtomicInteger();assertTrue(ChocolateQueueRecovery.matchesInspection(i,declared,declared.observed(),0,NOW));assertFalse(ChocolateQueueRecovery.matchesInspection(i,declared,replacement(false),0,NOW));assertFalse(ChocolateQueueRecovery.matchesInspection(i,declared,declared.observed(),1,NOW));assertFalse(ChocolateQueueRecovery.matchesInspection(i,declared,declared.observed(),0,2001));if(ChocolateQueueRecovery.matchesInspection(i,declared,replacement(false),0,NOW))writes.incrementAndGet();assertEquals(0,writes.get());assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,c.runtime().state());}

    @Test void newerSameScopeIntentDuringFlushSurvivesWhileOriginalArchiveRemainsPending(){var c=ChocolateQueueManualReconciliationTest.unknown();var i=intent(c);var rt=restarted();var plan=ChocolateQueueRecovery.prepare(i,c.pending(),inspect(i,true),true,rt,NOW);var memory=new AtomicReference<>(ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode("").withContract(i).with(c.pending())));var nextId=new AtomicReference<String>();assertFalse(ChocolateManualReconciliationTransaction.commit(plan.pending(),plan.resolved(),j->memory.set(ChocolateFactoryHistory.decode(memory.get().withManualQueueJournal(j))),()->{assertTrue(rt.selectQueue(c.profile(),ChocolateQueueManualReconciliationTest.observation(false),List.of("employee"),new BigDecimal("100"),BigDecimal.ZERO,NOW));nextId.set(rt.selection().intentId());var next=new ChocolateFactoryModule.Journal(1,i.scope(),"2026-09-30","PENDING","employee","100","0","new intent","0",nextId.get());memory.set(ChocolateFactoryHistory.decode(memory.get().withContract(ChocolateQueueIntent.capture(rt,c.profile())).with(next)));return true;},()->ChocolateQueueRecovery.unchangedRuntime(rt,plan),()->rt.closeRecoveryReconciliation(plan),()->rt.restoreOwnedManualClosure(plan.runtimeBefore())));assertEquals(nextId.get(),rt.selection().intentId());assertEquals(nextId.get(),memory.get().profiles().get(i.scope()).intentId());assertEquals("UNKNOWN",memory.get().queueIntents().get(i.id()).status());assertEquals("PENDING",memory.get().queueIntents().get(nextId.get()).status());assertEquals(0,rt.manualDeclaredDebit().signum());assertTrue(memory.get().receipts().isEmpty());assertThrows(IllegalStateException.class,()->rt.restoreOwnedManualClosure(plan.runtimeBefore()));}

}
